"use client";

import { useState } from "react";
import { supabase } from "./lib/supabase";

type StartAttemptResult = {
  attempt_id: string;
  resumed: boolean;
};

function getDeviceToken(): string {
  const storageKey = "quiz_device_token";
  const existing = window.localStorage.getItem(storageKey);
  if (existing) return existing;

  const created = window.crypto.randomUUID();
  window.localStorage.setItem(storageKey, created);
  return created;
}

export default function HomePage() {
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [className, setClassName] = useState("");
  const [privacyRead, setPrivacyRead] = useState(false);
  const [message, setMessage] = useState("");
  const [submitting, setSubmitting] = useState(false);

  async function startQuiz() {
    if (!firstName.trim() || !lastName.trim() || !className.trim()) {
      setMessage("Įrašykite vardą, pavardę ir klasę.");
      return;
    }

    if (!privacyRead) {
      setMessage("Patvirtinkite, kad susipažinote su privatumo informacija.");
      return;
    }

    setSubmitting(true);
    setMessage("");

    const deviceToken = getDeviceToken();
    const { data, error } = await supabase.rpc("start_quiz_attempt", {
      p_first_name: firstName.trim(),
      p_last_name: lastName.trim(),
      p_class_name: className.trim(),
      p_device_token: deviceToken,
      p_privacy_accepted: true,
    });

    if (error) {
      console.error(error);
      setMessage(error.message || "Nepavyko pradėti testo.");
      setSubmitting(false);
      return;
    }

    const result = data as StartAttemptResult | null;
    if (!result?.attempt_id) {
      setMessage("Nepavyko gauti bandymo numerio.");
      setSubmitting(false);
      return;
    }

    window.localStorage.setItem("quiz_attempt_id", result.attempt_id);
    window.location.assign(`/quiz?attempt=${encodeURIComponent(result.attempt_id)}`);
  }

  return (
    <main className="min-h-screen bg-slate-100 p-4 sm:p-10">
      <section className="mx-auto w-full max-w-xl rounded-2xl bg-white p-6 shadow-lg sm:p-8">
        <h1 className="mb-3 text-3xl font-bold text-gray-900">Psichikos sveikatos diena</h1>
        <p className="mb-6 text-gray-600">Kuo greičiau pasirinksite visus tinkamiausius atsakymus, tuo daugiau taškų gausite. Prie ankstesnių klausimų grįžti nebus galima.</p>

        <div className="space-y-4">
          <label className="block">
            <span className="mb-1 block text-sm font-medium">Vardas</span>
            <input value={firstName} onChange={(event) => setFirstName(event.target.value)} autoComplete="given-name" className="w-full rounded-xl border border-gray-300 p-3" />
          </label>

          <label className="block">
            <span className="mb-1 block text-sm font-medium">Pavardė</span>
            <input value={lastName} onChange={(event) => setLastName(event.target.value)} autoComplete="family-name" className="w-full rounded-xl border border-gray-300 p-3" />
          </label>

          <label className="block">
            <span className="mb-1 block text-sm font-medium">Klasė</span>
            <input value={className} onChange={(event) => setClassName(event.target.value)} placeholder="Pavyzdžiui, 7A" className="w-full rounded-xl border border-gray-300 p-3" />
          </label>

          <div className="rounded-xl border border-blue-200 bg-blue-50 p-4 text-sm text-gray-700">
            <p className="font-semibold text-gray-900">Privatumo informacija</p>
            <p className="mt-2">Viktorinai vykdyti bus tvarkomi vardas, pavardė, klasė, pasirinkti atsakymai, atsakymo trukmė ir techniniai testo sąžiningumo indikatoriai. Duomenys naudojami viktorinai administruoti, rezultatams apskaičiuoti ir galimiems neatitikimams peržiūrėti.</p>
          </div>
          <div className="rounded-xl border border-amber-300 bg-amber-50 p-4 text-sm text-gray-800">
            <p className="font-semibold text-gray-900">
              Kaip atlikti viktoriną?
            </p>

            <p className="mt-2">
              Klausimuose pasirinkite visus teisingus atsakymus.
              Teisingų atsakymų gali būti vienas, du, trys arba
              keturi.
            </p>

            <p className="mt-2">
              Kuo greičiau pateiksite{" "}
              <strong>teisingą atsakymą arba atsakymus</strong>,
              tuo daugiau taškų gausite.
            </p>

            <p className="mt-2 font-semibold">
              Sėkmės!
            </p>
          </div>

          <label className="flex items-start gap-3 rounded-xl border border-gray-300 p-4">
            <input type="checkbox" checked={privacyRead} onChange={(event) => setPrivacyRead(event.target.checked)} className="mt-1 h-4 w-4" />
            <span className="text-sm">Susipažinau su aukščiau pateikta privatumo informacija.</span>
          </label>

          {message ? <p className="rounded-xl bg-red-50 p-3 text-sm text-red-700">{message}</p> : null}

          <button type="button" onClick={startQuiz} disabled={submitting} className="w-full rounded-xl bg-blue-600 px-6 py-3 font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-gray-400">
            {submitting ? "Ruošiamas testas..." : "Pradėti testą"}
          </button>
        </div>
      </section>
    </main>
  );
}

