"use client";

import { useCallback, useEffect, useState } from "react";
import { supabase } from "../lib/supabase";

type AnswerOption = {
  id: string;
  answer_text: string;
};

type AttemptState = {
  completed: boolean;
  total_score: number;
  answered_count: number;
  total_questions: number;
  question_id?: string;
  question_text?: string;
  answers?: AnswerOption[];
  question_number?: number;
};

type SubmitResult = {
  saved: boolean;
  completed: boolean;
  total_score: number;
  answered_count: number;
};

function getAttemptId(): string {
  const query = new URLSearchParams(window.location.search);
  return query.get("attempt") ?? window.localStorage.getItem("quiz_attempt_id") ?? "";
}

function getDeviceToken(): string {
  return window.localStorage.getItem("quiz_device_token") ?? "";
}

export default function QuizPage() {
  const [state, setState] = useState<AttemptState | null>(null);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");

  const loadAttempt = useCallback(async () => {
    setLoading(true);
    setErrorMessage("");

    const attemptId = getAttemptId();
    const deviceToken = getDeviceToken();

    if (!attemptId || !deviceToken) {
      setErrorMessage("Bandymo duomenys nerasti. Grįžkite į pradinį puslapį ir pradėkite testą iš naujo.");
      setLoading(false);
      return;
    }

    window.localStorage.setItem("quiz_attempt_id", attemptId);

    const { data, error } = await supabase.rpc("get_attempt_state", {
      p_attempt_id: attemptId,
      p_device_token: deviceToken,
    });

    if (error) {
      console.error(error);
      setErrorMessage(error.message || "Nepavyko įkelti bandymo.");
      setLoading(false);
      return;
    }

    setState(data as AttemptState);
    setSelectedIds([]);
    setLoading(false);
  }, []);

  useEffect(() => {
    void loadAttempt();
  }, [loadAttempt]);

  function toggleAnswer(answerId: string) {
    setSelectedIds((current) =>
      current.includes(answerId)
        ? current.filter((id) => id !== answerId)
        : [...current, answerId]
    );
  }

  async function submitAnswer() {
    if (!state?.question_id || selectedIds.length === 0 || submitting) return;

    setSubmitting(true);
    setErrorMessage("");

    const attemptId = getAttemptId();
    const deviceToken = getDeviceToken();

    const { data, error } = await supabase.rpc("submit_attempt_answer", {
      p_attempt_id: attemptId,
      p_device_token: deviceToken,
      p_question_id: state.question_id,
      p_selected_answer_ids: selectedIds,
    });

    if (error) {
      console.error(error);
      setErrorMessage(error.message || "Nepavyko išsaugoti atsakymo.");
      setSubmitting(false);
      return;
    }

    const result = data as SubmitResult;

    if (result.completed) {
      setState({
        completed: true,
        total_score: result.total_score,
        answered_count: result.answered_count,
        total_questions: state.total_questions,
      });
      setSelectedIds([]);
      setSubmitting(false);
      return;
    }

    setSubmitting(false);
    await loadAttempt();
  }

  if (loading) {
    return (
      <main className="min-h-screen grid place-items-center bg-slate-100 p-6">
        <p className="text-lg font-semibold">Kraunamas bandymas...</p>
      </main>
    );
  }

  if (errorMessage && !state) {
    return (
      <main className="min-h-screen grid place-items-center bg-slate-100 p-6">
        <section className="w-full max-w-lg rounded-2xl bg-white p-8 text-center shadow-lg">
          <h1 className="mb-3 text-2xl font-bold">Nepavyko atidaryti testo</h1>
          <p className="mb-6 text-red-700">{errorMessage}</p>
          <a href="/" className="inline-block rounded-xl bg-blue-600 px-6 py-3 font-semibold text-white">Grįžti į pradžią</a>
        </section>
      </main>
    );
  }

  if (state?.completed) {
    return (
      <main className="min-h-screen grid place-items-center bg-slate-100 p-6">
        <section className="w-full max-w-lg rounded-2xl bg-white p-8 text-center shadow-lg">
          <h1 className="mb-3 text-3xl font-bold">Testas baigtas</h1>
          <p className="text-2xl font-bold text-blue-700">Surinkta taškų: {state.total_score}</p>
          <p className="mt-4 text-sm text-gray-600">Su teisingais atsakymais būsite supažindinti vėliau.</p>
        </section>
      </main>
    );
  }

  if (!state?.question_id || !state.question_text || !state.answers) return null;

  const progress = ((state.question_number ?? 1) / state.total_questions) * 100;

  return (
    <main className="min-h-screen bg-slate-100 p-4 sm:p-10">
      <section className="mx-auto w-full max-w-3xl rounded-2xl bg-white p-6 shadow-lg sm:p-8">
        <div className="mb-2 flex items-center justify-between text-sm text-gray-500">
          <span>Klausimas {state.question_number} iš {state.total_questions}</span>
          <span>Atsakyta: {state.answered_count}</span>
        </div>

        <div className="mb-7 h-2 overflow-hidden rounded-full bg-gray-200">
          <div className="h-full bg-blue-600 transition-all" style={{ width: `${progress}%` }} />
        </div>

        <p className="mb-3 text-sm font-semibold text-blue-700">Pažymėkite visus tinkamus atsakymus.</p>
        <h1 className="mb-7 text-2xl font-bold leading-snug text-gray-900">{state.question_text}</h1>

        <div className="space-y-3">
          {state.answers.map((answer) => {
            const selected = selectedIds.includes(answer.id);
            return (
              <label key={answer.id} className={selected ? "block cursor-pointer rounded-xl border border-blue-600 bg-blue-50 p-4" : "block cursor-pointer rounded-xl border border-gray-300 bg-white p-4 hover:border-blue-400"}>
                <input type="checkbox" checked={selected} onChange={() => toggleAnswer(answer.id)} className="mr-3 h-4 w-4" />
                <span className="text-gray-900">{answer.answer_text}</span>
              </label>
            );
          })}
        </div>

        {errorMessage ? <p className="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{errorMessage}</p> : null}

        <button type="button" onClick={submitAnswer} disabled={selectedIds.length === 0 || submitting} className="mt-7 w-full rounded-xl bg-blue-600 px-6 py-3 font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-gray-400">
          {submitting ? "Išsaugoma..." : state.question_number === state.total_questions ? "Baigti testą" : "Kitas klausimas"}
        </button>

        <p className="mt-4 text-center text-xs text-gray-500">Atsakymas išsaugomas automatiškai. Prie ankstesnio klausimo grįžti negalima.</p>
      </section>
    </main>
  );
}
